H=W=30
G=[[3]*W for _ in range(H)]
objs={
'9': (4, [[9,9,9],[9,0,9],[9,9,9]]),
'8': (21, [[8,0,0],[8,0,0],[8,8,8]]),
'5': (12, [[5,0],[5,5]]),
'1': (22, [[1,1,1],[1,0,1],[1,1,1],[0,1,0]]),
'4': (4, [[0,4,0],[4,4,4]]),
'2': (16, [[2,2],[2,0]]),
}
# top group packed at row 0, bottom group at bottom edge
for k in ['9','8','5']:
 c,sh=objs[k]
 for r,row in enumerate(sh):
  for j,v in enumerate(row):
   if v:G[r][c+j]=v
for k in ['1','4','2']:
 c,sh=objs[k]; start=H-len(sh)
 for i,row in enumerate(sh):
  for j,v in enumerate(row):
   if v:G[start+i][c+j]=v
print('\n'.join(' '.join(map(str,row)) for row in G))
